<script setup>defineProps({loading:Boolean,results:Array});</script><template><section class="results card"><div class="result-head"><h2>识别结果</h2><span v-if="loading" class="progress">识别中 · 请稍候</span></div><div v-if="!loading&&!results.length" class="empty">开始测评后将在这里并排展示各模型结果</div><div class="result-grid"><article v-for="r in results" :key="r.id"><div class="result-title"><b>{{r.provider}}</b><span :class="r.status">{{r.status==='completed'?'已完成':r.status}}</span></div><p>{{r.text}}</p><small v-if="r.duration">耗时 {{r.duration}} ms</small></article></div></section>
</template>